      intents: [],
      next_entry_id: 1000,
      money_before: { 101 => before_snapshot },
      money_after: { 101 => after_snapshot }
    )
    expect(result.companies.fetch(101).abort?).to be(true)
    expect(result.companies.fetch(101).checks.fetch(:money)).not_to be_empty

