RSpec.describe Timekeeping::Handoff::Reconciliation do
  # "Reconciliation only reads; it writes no billing table and repairs nothing."
  # Emitting an event stores it through the event subscriber, so event storage writes are the only writes allowed.
  it "reports differences without writing any billing table or changing the result it was given" do
    entry = lambda do |id, company_id, duration|
      {
        "id" => id, "company_id" => company_id, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
        "work_date" => Date.new(2026, 1, 5), "duration" => duration, "note" => "", "bill_status" => "unbilled",
        "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
        "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => Time.utc(2026, 1, 5, 9), "updated_at" => Time.utc(2026, 1, 5, 9)
      }
    end
    source_tables = Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }
    source_tables["entries"] = [entry.call(1, 101, 60.0)]
    checkpoint_tables = source_tables.merge("entries" => [entry.call(1, 101, 60.0.next_float)])
    snapshots = { 101 => { company_id: 101, values: {} } }
    result = described_class.run(
      source: Timekeeping::Handoff::Checkpoint.build(tables: source_tables),
      checkpoint: Timekeeping::Handoff::Checkpoint.build(tables: checkpoint_tables),
      projection: [], source_intents: [], intents: [], next_entry_id: 100,
      money_before: snapshots, money_after: snapshots
    )
    report_before = result.to_h

    writes = []
    subscriber = ActiveSupport::Notifications.subscribe("sql.active_record") do |*, payload|
      sql = payload[:sql].to_s
      writes << sql if sql.match?(/\A\s*(INSERT|UPDATE|DELETE)/i) && !sql.include?("rails_event_viewer")
    end
    begin
      returned = described_class.report(result)
    ensure
      ActiveSupport::Notifications.unsubscribe(subscriber)
    end

    expect(writes).to eq([])
    expect(returned.to_h).to eq(report_before)
    expect(returned.abort?).to be(true)
    expect(checkpoint_tables["entries"].first["duration"]).to eq(60.0.next_float)
  end
end

RSpec.describe Timekeeping::ReconciliationDifferenceFound do
  let(:reconciliation_event_difference) do
    Data.define(:company_id, :check, :table, :row_key, :field, :reason, :note, :duration)
  end

  it "names the difference by identifiers only" do
    difference = reconciliation_event_difference.new(
      company_id: 101, check: :entries, table: "entries", row_key: [7], field: "note", reason: :changed,
      note: "private-memo-text", duration: 61.25
    )

    data = described_class.new(difference, listed: false, actor: nil).to_h[:data]

    expect(data).to eq(
      company_id: 101, check: :entries, table: "entries", row_key: [7], field: "note", reason: :changed, listed: false
    )
    expect(JSON.generate(data)).not_to include("private-memo-text")
    expect(JSON.generate(data)).not_to include("61.25")
  end

  it "marks a difference the pre-flight listed" do
    difference = reconciliation_event_difference.new(
      company_id: 202, check: :projection, table: "entries", row_key: [7], field: "locked", reason: :changed,
      note: nil, duration: nil
    )

    data = described_class.new(difference, listed: true, actor: nil).to_h[:data]

    expect(data[:listed]).to be(true)
    expect(data[:company_id]).to eq(202)
  end
end

RSpec.describe Timekeeping::Handoff::Reconciliation, "check by check" do
  let(:recon_checks_time) { Time.utc(2026, 1, 5, 9) }
  let(:recon_checks_operation_id) { "11111111-1111-1111-1111-111111111111" }

  def recon_checks_entry(company_id, **overrides)
    {
      "id" => 1, "company_id" => company_id, "version" => 1, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
      "work_date" => Date.new(2026, 1, 5), "duration" => 60.0, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => true, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => recon_checks_time, "updated_at" => recon_checks_time
    }.merge(overrides.transform_keys(&:to_s))
  end

  def recon_checks_reservation(company_id, **overrides)
    { "company_id" => company_id, "entry_id" => 1, "invoice_id" => 1, "state" => "committed",
      "disposition" => "active", "operation_id" => recon_checks_operation_id,
      "created_at" => recon_checks_time }
      .reverse_merge(Timekeeping::Handoff::Checkpoint::TABLES.fetch("reservations").index_with { nil })
      .merge(overrides.transform_keys(&:to_s))
  end

  def recon_checks_operation(company_id, **overrides)
    { "id" => 1, "company_id" => company_id, "invoice_id" => 1, "operation_id" => recon_checks_operation_id,
      "state" => "committed", "desired_entry_ids" => [1], "disposition" => "active", "generation" => 1,
      "created_at" => recon_checks_time, "finished_at" => recon_checks_time }.merge(overrides.transform_keys(&:to_s))
  end

  def recon_checks_intent(company_id, **overrides)
    { "company_id" => company_id, "invoice_id" => 1, "operation_id" => recon_checks_operation_id, "generation" => 1,
      "desired_entry_ids" => [1], "disposition" => "active", "state" => "committed", "created_at" => recon_checks_time,
      "finished_at" => recon_checks_time }.merge(overrides.transform_keys(&:to_s))
  end

  def recon_checks_audit(company_id, **overrides)
    { "id" => 1, "company_id" => company_id, "entry_id" => 1, "actor_type" => "User", "actor_id" => 1,
      "action" => "create", "before" => nil, "after" => { "note" => "" },
      "entry_created_at" => recon_checks_time, "created_at" => recon_checks_time }.merge(overrides.transform_keys(&:to_s))
  end

  def recon_checks_receipt(company_id, **overrides)
    { "id" => 1, "company_id" => company_id, "actor_type" => "User", "actor_id" => 1, "operation" => "create_entry",
      "key" => "key-1", "fingerprint" => "abc", "status" => 201, "body" => { "id" => 1 },
      "created_at" => recon_checks_time }.merge(overrides.transform_keys(&:to_s))
  end

  # Both companies hold the same ids, so a check keyed by row id alone would mix them.
  def recon_checks_tables(**changes_for_a)
    tables = {
      "entries" => [recon_checks_entry(101), recon_checks_entry(202)],
      "reservations" => [recon_checks_reservation(101), recon_checks_reservation(202)],
      "invoice_operations" => [recon_checks_operation(101), recon_checks_operation(202)],
      "entry_audits" => [recon_checks_audit(101), recon_checks_audit(202)],
      "idempotency_records" => [recon_checks_receipt(101), recon_checks_receipt(202)],
      "service_idempotency_receipts" => []
    }
    changes_for_a.each do |table, rows_for_a|
      tables[table.to_s] = rows_for_a + tables[table.to_s].reject { |row| row["company_id"] == 101 }
    end
    recon_checks_canonical(tables)
  end

  # Fills every canonical checkpoint column a fixture row leaves out with nil,
  # so the rows keep fitting Checkpoint::TABLES when it gains a column.
  def recon_checks_canonical(tables)
    tables.to_h do |table, rows|
      defaults = Timekeeping::Handoff::Checkpoint::TABLES.fetch(table).index_with { nil }
      [table, rows.map { |row| row.reverse_merge(defaults) }]
    end
  end

  def recon_checks_run(checkpoint_tables: recon_checks_tables, projection: nil, source_tables: recon_checks_tables,
                       intents: [recon_checks_intent(101), recon_checks_intent(202)],
                       source_intents: [recon_checks_intent(101), recon_checks_intent(202)], **options)
    source_tables = recon_checks_canonical(source_tables)
    checkpoint_tables = recon_checks_canonical(checkpoint_tables)
    projection ||= checkpoint_tables["entries"].map do |row|
      row.merge(
        "bill_status" => TimesheetEntry.bill_statuses.fetch(row["bill_status"]),
        "review_status" => TimesheetEntry.review_statuses.fetch(row["review_status"])
      )
    end
    money = [101, 202].index_with { |company_id| { company_id:, values: {} } }
    described_class.run(
      source: Timekeeping::Handoff::Checkpoint.build(tables: source_tables),
      checkpoint: Timekeeping::Handoff::Checkpoint.build(tables: checkpoint_tables),
      projection:, source_intents:, intents:,
      next_entry_id: 2, money_before: money, money_after: money, **options
    )
  end

  def expect_recon_checks_abort_in_a(result, check, reason:, field: :any)
    differences = result.companies.fetch(101).checks.fetch(check)
    expect(differences.map(&:reason)).to include(reason)
    expect(differences.map(&:field)).to include(field) unless field == :any
    expect(differences.map(&:company_id).uniq).to eq([101])
    expect(result.companies.fetch(101)).to be_abort
    expect(result.companies.fetch(202)).not_to be_abort
    expect(result.companies.fetch(202).checks.values.flatten).to eq([])
  end

  it "passes the shared fixture unchanged" do
    result = recon_checks_run
    expect(result).not_to be_abort
    expect(result.to_h.fetch("companies").keys).to contain_exactly(101, 202)
  end

  it "reports a changed version and an extra entry under the company they belong to" do
    changed = recon_checks_run(checkpoint_tables: recon_checks_tables(entries: [recon_checks_entry(101, version: 2)]))
    expect_recon_checks_abort_in_a(changed, :entries, reason: :changed, field: "version")

    extra = recon_checks_tables(entries: [recon_checks_entry(101), recon_checks_entry(101, id: 9, locked: false)])
    result = recon_checks_run(checkpoint_tables: extra)
    expect_recon_checks_abort_in_a(result, :entries, reason: :missing_in_source)
  end

  it "reports a changed per-user month total" do
    tables = recon_checks_tables(entries: [recon_checks_entry(101, duration: 90.0)])
    result = recon_checks_run(checkpoint_tables: tables)
    totals = result.companies.fetch(101).checks.fetch(:totals)
    expect(totals.map { |difference| [difference.row_key, difference.field] })
      .to include([[], "duration_sum"], [[1, "2026-01"], "duration_sum"])
    expect(result.companies.fetch(202).checks.fetch(:totals)).to eq([])
  end

  it "reports a reservation whose owner invoice changed" do
    tables = recon_checks_tables(reservations: [recon_checks_reservation(101, invoice_id: 404)])
    result = recon_checks_run(checkpoint_tables: tables)
    expect_recon_checks_abort_in_a(result, :reservations, reason: :changed, field: "invoice_id")
  end

  it "compares reservations with the pre-flight's classification on the first cutover" do
    expected = {
      101 => [{ "entry_id" => 1, "state" => "committed", "invoice_id" => 1, "disposition" => "retained" }],
      202 => [{ "entry_id" => 1, "state" => "committed", "invoice_id" => 1, "disposition" => "active" }]
    }
    result = recon_checks_run(expected_reservations: expected)
    expect_recon_checks_abort_in_a(result, :reservation_classification, reason: :changed, field: "disposition")
  end

  it "refuses a classification row filed under a company other than its own" do
    misfiled = {
      101 => [recon_checks_reservation(202)],
      202 => [recon_checks_reservation(202)]
    }
    expect { recon_checks_run(expected_reservations: misfiled) }
      .to raise_error(ArgumentError, /filed under company 101/)

    filed_right = { 101 => [recon_checks_reservation(101)], 202 => [recon_checks_reservation(202)] }
    expect(recon_checks_run(expected_reservations: filed_right)).not_to be_abort
  end

  it "reports a changed audit row and a changed idempotency receipt by count or checksum" do
    audits = recon_checks_run(checkpoint_tables: recon_checks_tables(entry_audits: [recon_checks_audit(101, action: "update")]))
    expect_recon_checks_abort_in_a(audits, :audit_rows, reason: :changed, field: "checksum")

    receipts = recon_checks_run(checkpoint_tables: recon_checks_tables(idempotency_records: []))
    expect_recon_checks_abort_in_a(receipts, :idempotency_receipts, reason: :changed, field: "count")
  end

  it "reports a changed intent generation and an extra intent" do
    changed = recon_checks_run(intents: [recon_checks_intent(101, generation: 2), recon_checks_intent(202)])
    expect_recon_checks_abort_in_a(changed, :operation_receipts, reason: :changed, field: "generation")

    other_operation = "22222222-2222-2222-2222-222222222222"
    extra = recon_checks_run(
      intents: [recon_checks_intent(101), recon_checks_intent(101, operation_id: other_operation, state: "failed"),
                recon_checks_intent(202)]
    )
    expect_recon_checks_abort_in_a(extra, :operation_receipts, reason: :missing_in_source)
  end

  it "requires a committed intent to have a committed operation and a failed intent an aborted one or none" do
    aborted = recon_checks_tables(invoice_operations: [recon_checks_operation(101, state: "aborted")])
    without_commit = recon_checks_run(checkpoint_tables: aborted)
    expect_recon_checks_abort_in_a(without_commit, :operation_receipts, reason: :intent_without_committed_operation)

    failed = recon_checks_run(intents: [recon_checks_intent(101, state: "failed"), recon_checks_intent(202)])
    expect_recon_checks_abort_in_a(failed, :operation_receipts, reason: :failed_intent_with_unaborted_operation)
  end

  it "does not let a correction for another row of the same company explain a difference" do
    tables = recon_checks_tables(entries: [recon_checks_entry(101, note: "changed")])
    correction = described_class::Correction.new(check: :entries, row_key: [2], field: "note")
    result = recon_checks_run(checkpoint_tables: tables, listed_corrections: { 101 => [correction] })
    expect_recon_checks_abort_in_a(result, :entries, reason: :changed, field: "note")
    expect(result.companies.fetch(101).listed).to eq([])
  end

  it "signals a listed difference with listed true" do
    tables = recon_checks_tables(entries: [recon_checks_entry(101, note: "changed")])
    correction = described_class::Correction.new(check: :entries, row_key: [1], field: "note")
    result = recon_checks_run(checkpoint_tables: tables, listed_corrections: { 101 => [correction] })
    expect(result).not_to be_abort

    stored = RailsEventViewer::Entry.where(name: "Timekeeping::ReconciliationDifferenceFound")
    expect { described_class.report(result) }.to change { stored.count }.by(1)

    data = stored.order(:id).last.payload["data"]
    expect(data).to include("company_id" => 101, "check" => "entries", "field" => "note", "listed" => true)
  end

  it "signals a missing money snapshot only as a reconciliation difference" do
    money = { 202 => { company_id: 202, values: {} } }
    result = described_class.run(
      source: Timekeeping::Handoff::Checkpoint.build(tables: recon_checks_tables),
      checkpoint: Timekeeping::Handoff::Checkpoint.build(tables: recon_checks_tables),
      projection: recon_checks_tables["entries"].map do |row|
        row.merge(
          "bill_status" => TimesheetEntry.bill_statuses.fetch(row["bill_status"]),
          "review_status" => TimesheetEntry.review_statuses.fetch(row["review_status"])
        )
      end,
      source_intents: [recon_checks_intent(101), recon_checks_intent(202)],
      intents: [recon_checks_intent(101), recon_checks_intent(202)],
      next_entry_id: 2, money_before: money, money_after: money
    )
    expect(result.companies.fetch(101).unlisted.map(&:reason)).to eq(%i[snapshot_missing snapshot_missing])

    stored = RailsEventViewer::Entry.where(name: "Timekeeping::ReconciliationDifferenceFound")
    assert_no_event_reported("Timekeeping::FinancialSnapshotChanged") do
      expect { described_class.report(result) }.to change { stored.count }.by(2)
    end
    expect(stored.order(:id).last(2).map { |row| row.payload["data"]["company_id"] }).to eq([101, 101])
  end

  it "separates totals by user and by month when the company total is unchanged" do
    entries = lambda do |durations|
      [
        recon_checks_entry(101, duration: durations[0]),
        recon_checks_entry(101, id: 2, duration: durations[1], work_date: Date.new(2026, 2, 3), locked: false),
        recon_checks_entry(101, id: 3, user_id: 2, duration: durations[2], locked: false)
      ]
    end
    result = recon_checks_run(
      source_tables: recon_checks_tables(entries: entries.call([60.0, 60.0, 60.0])),
      checkpoint_tables: recon_checks_tables(entries: entries.call([90.0, 45.0, 45.0]))
    )

    totals = result.companies.fetch(101).checks.fetch(:totals)
    expect(totals.map { |difference| [difference.row_key, difference.field] }).to contain_exactly(
      [[1, "2026-01"], "duration_sum"], [[1, "2026-02"], "duration_sum"], [[2, "2026-01"], "duration_sum"]
    )
    expect(result.companies.fetch(101)).to be_abort
    expect(result.companies.fetch(202).checks.values.flatten).to eq([])
  end

  it "reports a changed count when an entry moves to another month" do
    moved = [recon_checks_entry(101), recon_checks_entry(101, id: 2, locked: false)]
    result = recon_checks_run(
      source_tables: recon_checks_tables(entries: moved),
      checkpoint_tables: recon_checks_tables(entries: [moved[0], moved[1].merge("work_date" => Date.new(2026, 2, 3))])
    )
    totals = result.companies.fetch(101).checks.fetch(:totals)
    expect(totals.map { |difference| [difference.row_key, difference.field, difference.reason] })
      .to include([[1, "2026-01"], "count", :changed], [[1, "2026-02"], nil, :missing_in_source])
    expect(result.companies.fetch(202).checks.fetch(:totals)).to eq([])
  end

  it "passes a failed intent whose operation aborted and a failed intent with no operation" do
    failed_intents = [recon_checks_intent(101, state: "failed"), recon_checks_intent(202)]
    aborted = recon_checks_tables(invoice_operations: [recon_checks_operation(101, state: "aborted")])
    with_abort = recon_checks_run(
      source_tables: aborted, checkpoint_tables: aborted, intents: failed_intents, source_intents: failed_intents
    )
    expect(with_abort.companies.fetch(101).checks.fetch(:operation_receipts)).to eq([])
    expect(with_abort).not_to be_abort

    no_operation = recon_checks_tables(invoice_operations: [])
    without = recon_checks_run(
      source_tables: no_operation, checkpoint_tables: no_operation, intents: failed_intents,
      source_intents: failed_intents
    )
    expect(without.companies.fetch(101).checks.fetch(:operation_receipts)).to eq([])
    expect(without).not_to be_abort
  end

  it "reports a changed operation row whose state rules still hold" do
    tables = recon_checks_tables(invoice_operations: [recon_checks_operation(101, desired_entry_ids: [1, 2])])
    result = recon_checks_run(checkpoint_tables: tables)
    differences = result.companies.fetch(101).checks.fetch(:operation_receipts)
    expect(differences.map { |difference| [difference.table, difference.row_key, difference.field, difference.reason] })
      .to eq([["invoice_operations", [1], "desired_entry_ids", :changed]])
    expect_recon_checks_abort_in_a(result, :operation_receipts, reason: :changed, field: "desired_entry_ids")
  end

  it "does not let another invoice's committed operation settle an intent" do
    other_invoice_intents = [recon_checks_intent(101, invoice_id: 20), recon_checks_intent(202)]
    result = recon_checks_run(intents: other_invoice_intents, source_intents: other_invoice_intents)
    expect_recon_checks_abort_in_a(result, :operation_receipts, reason: :intent_without_committed_operation)
  end

  it "does not let an operation row correction explain the matching intent row change" do
    tables = recon_checks_tables(invoice_operations: [recon_checks_operation(101, invoice_id: 2)])
    intents = [recon_checks_intent(101, invoice_id: 2), recon_checks_intent(202)]
    correction = described_class::Correction.new(
      check: :operation_receipts, row_key: [1], field: "invoice_id"
    )
    result = recon_checks_run(checkpoint_tables: tables, intents:, listed_corrections: { 101 => [correction] })

    report = result.companies.fetch(101)
    expect(report.listed.map(&:table)).to eq(["invoice_operations"])
    expect(report.unlisted.map(&:table).uniq).to eq(["invoice_operation_intents"])
    expect(report).to be_abort
  end

  it "passes unchanged receipts of two invoices that reuse one operation id" do
    operations = [recon_checks_operation(101, id: 1, invoice_id: 10), recon_checks_operation(101, id: 2, invoice_id: 20)]
    tables = recon_checks_tables(invoice_operations: operations)
    intents = [recon_checks_intent(101, invoice_id: 10), recon_checks_intent(101, invoice_id: 20), recon_checks_intent(202)]
    result = recon_checks_run(source_tables: tables, checkpoint_tables: tables, intents:, source_intents: intents)

    expect(result.companies.fetch(101).checks.fetch(:operation_receipts)).to eq([])
    expect(result).not_to be_abort
  end

  it "still aborts on a duplicate committed reservation when the added row is listed" do
    source = recon_checks_tables(reservations: [])
    loaded = recon_checks_tables(reservations: [recon_checks_reservation(101), recon_checks_reservation(101, invoice_id: 2)])
    correction = described_class::Correction.new(check: :reservations, row_key: [1, "committed"], field: nil)
    result = recon_checks_run(source_tables: source, checkpoint_tables: loaded, listed_corrections: { 101 => [correction] })

    report = result.companies.fetch(101)
    expect(report.listed.map(&:reason)).to include(:missing_in_source)
    expect(report.unlisted.map(&:reason)).to include(:duplicate_key)
    expect(report).to be_abort
    expect(result.companies.fetch(202)).not_to be_abort
  end

  it "keeps an unmatched projection row with a company under that company" do
    source = recon_checks_tables.merge(
      "entries" => [recon_checks_entry(101, id: 7, locked: false), recon_checks_entry(202, id: 8, locked: false)],
      "reservations" => []
    )
    projection = (source["entries"] + [recon_checks_entry(202, id: 7, locked: false)]).map do |row|
      row.merge(
        "bill_status" => TimesheetEntry.bill_statuses.fetch(row["bill_status"]),
        "review_status" => TimesheetEntry.review_statuses.fetch(row["review_status"])
      )
    end
    result = recon_checks_run(source_tables: source, checkpoint_tables: source, projection:)

    expect(result.companies.fetch(101).checks.fetch(:projection)).to eq([])
    expect(result.companies.fetch(202).checks.fetch(:projection).map { |difference| [difference.row_key, difference.reason] })
      .to eq([[[7], :missing_in_checkpoint]])
    expect(result.companies.fetch(202)).to be_abort
    expect(result.unassigned).to eq([])
  end

  it "reports a projection that unlocked an entry the checkpoint keeps locked" do
    unreserved = recon_checks_tables(reservations: [])
    projection = unreserved["entries"].map do |row|
      row.merge(
        "bill_status" => TimesheetEntry.bill_statuses.fetch(row["bill_status"]),
        "review_status" => TimesheetEntry.review_statuses.fetch(row["review_status"]),
        "locked" => row["company_id"] == 202
      )
    end
    result = recon_checks_run(
      source_tables: recon_checks_tables(reservations: []), checkpoint_tables: unreserved, projection:
    )
    expect_recon_checks_abort_in_a(result, :projection, reason: :changed, field: "locked")
  end

  it "reads no database while it runs" do
    recon_checks_run
    queries = []
    subscriber = ActiveSupport::Notifications.subscribe("sql.active_record") { |*, payload| queries << payload[:sql] }
    begin
      recon_checks_run
    ensure
      ActiveSupport::Notifications.unsubscribe(subscriber)
    end
    expect(queries).to eq([])
  end

  it "reports a stored discount and the printed values it moves, by identifiers only" do
    before_values = {
      [:invoice, 9, :discount] => BigDecimal("5"), [:pdf_total, 9, :invoice_discount] => "$5.00",
      [:pdf_total, 9, :total] => "$95.00"
    }
    after_values = {
      [:invoice, 9, :discount] => BigDecimal("15"), [:pdf_total, 9, :invoice_discount] => "$15.00",
      [:pdf_total, 9, :total] => "$85.00"
    }
    money_before = { 101 => { company_id: 101, values: before_values }, 202 => { company_id: 202, values: {} } }
    money_after = { 101 => { company_id: 101, values: after_values }, 202 => { company_id: 202, values: {} } }
    result = recon_checks_run(money_before:, money_after:)

    money = result.companies.fetch(101).checks.fetch(:money)
    expect(money.map { |difference| [difference.company_id, difference.row_key, difference.field] }).to contain_exactly(
      [101, [:invoice, 9], :discount], [101, [:pdf_total, 9], :invoice_discount], [101, [:pdf_total, 9], :total]
    )

    financial = RailsEventViewer::Entry.where(name: "Timekeeping::FinancialSnapshotChanged")
    reconciliation = RailsEventViewer::Entry.where(name: "Timekeeping::ReconciliationDifferenceFound")
    expect { described_class.report(result) }
      .to change { financial.count }.by(3).and change { reconciliation.count }.by(3)

    stored = financial.order(:id).last(3).map { |row| row.payload["data"] }
    expect(stored.map { |data| [data["company_id"], data["kind"], data["record_id"], data["field"]] })
      .to contain_exactly([101, "invoice", 9, "discount"], [101, "pdf_total", 9, "invoice_discount"],
                          [101, "pdf_total", 9, "total"])
    expect(reconciliation.order(:id).last(3).map { |row| row.payload["data"]["company_id"] }).to eq([101, 101, 101])
  end

  it "accepts every stored invoice_operation_intents column" do
    stored = ActiveRecord::Base.connection.columns("invoice_operation_intents").map(&:name)
    expect(stored - described_class::INTENT_COLUMNS).to eq([])
  end

  it "reports a changed desired entry set and a changed disposition on an intent" do
    changed = recon_checks_run(
      intents: [recon_checks_intent(101, desired_entry_ids: [2], disposition: "retained"), recon_checks_intent(202)]
    )
    fields = changed.companies.fetch(101).checks.fetch(:operation_receipts).map(&:field)
    expect(fields).to contain_exactly("desired_entry_ids", "disposition")
    expect_recon_checks_abort_in_a(changed, :operation_receipts, reason: :changed, field: "disposition")
  end

  it "accepts intent rows with their stored id and compares that id" do
    with_ids = [recon_checks_intent(101, id: 1), recon_checks_intent(202, id: 2)]
    expect(recon_checks_run(source_intents: with_ids, intents: with_ids)).not_to be_abort

    changed = recon_checks_run(
      source_intents: with_ids, intents: [recon_checks_intent(101, id: 9), recon_checks_intent(202, id: 2)]
    )
    expect_recon_checks_abort_in_a(changed, :operation_receipts, reason: :changed, field: "id")
  end

  it "keeps the check table frozen" do
    expect(described_class::CHECKS).to be_frozen
    expect(described_class::INTENT_RULES).to be_frozen
  end
end
